// Parse the Neo4j transactional response and build one candidate attack-path object per row.
// Assumes Asset nodes carry: name, exposure, criticality, exposedPorts, iacResourceAddress,
// iacFilePath, resourceType — see the setup sticky note for schema notes.
const config = $('Set Configuration Parameters').item.json;
const response = $input.item.json;

const results = (response.results && response.results[0]) || {};
const rows = results.data || [];

const paths = rows.map((entry, idx) => {
  const row = entry.row || [];
  const graph = entry.graph || {};
  const nodes = graph.nodes || [];

  const sourceName = row[1];
  const targetName = row[2];
  const targetCriticality = row[3];
  const hopCount = row[4];

  const misconfigNode = nodes.find(n => n.properties && n.properties.iacResourceAddress) || {};
  const exposedNode = nodes.find(n => (n.properties || {}).exposure === 'internet-facing') || nodes[0] || {};
  const targetNode = nodes[nodes.length - 1] || {};

  return {
    pathId: `PATH-${idx + 1}-${Date.now()}`,
    sourceAsset: sourceName || (exposedNode.properties || {}).name || 'unknown',
    targetAsset: targetName || (targetNode.properties || {}).name || 'unknown',
    targetCriticality: targetCriticality || (targetNode.properties || {}).criticality || 'unknown',
    hopCount: hopCount != null ? hopCount : nodes.length,
    exposedPorts: (exposedNode.properties || {}).exposedPorts || [],
    misconfigResourceAddress: (misconfigNode.properties || {}).iacResourceAddress || null,
    misconfigResourceType: (misconfigNode.properties || {}).resourceType || null,
    misconfigFilePath: (misconfigNode.properties || {}).iacFilePath || config.defaultIacPath,
    nodeCount: nodes.length
  };
});

return paths.map(p => ({ json: { ...config, ...p } }));

