# Composite risk scoring across all candidate attack paths; select the single highest-risk one
# Score = target criticality (40) + port exposure/exploitability (25) + hop proximity (20) + blast-radius density (15)
criticality_weights = {'crown-jewel': 40, 'critical': 32, 'high': 24, 'medium': 12, 'low': 4}
high_risk_ports = {22, 3389, 445, 1433, 3306, 5432, 6379, 9200, 27017}

scored = []
for i in _input.all():
    item = i['json']
    criticality = str(item.get('targetCriticality', '')).lower()
    criticality_score = criticality_weights.get(criticality, 10)

    exposed_ports = item.get('exposedPorts') or []
    port_hits = 0
    for p in exposed_ports:
        try:
            if int(p) in high_risk_ports:
                port_hits += 1
        except (ValueError, TypeError):
            continue
    exposure_score = min(10 + port_hits * 5, 25)

    try:
        hop_count = int(item.get('hopCount') or 10)
    except (ValueError, TypeError):
        hop_count = 10
    proximity_score = max(20 - (hop_count - 1) * 3, 2)

    node_count = item.get('nodeCount') or hop_count
    density_score = min(node_count * 1.5, 15)

    risk_score = round(criticality_score + exposure_score + proximity_score + density_score, 2)

    if risk_score >= 70:
        severity = 'Critical'
    elif risk_score >= 50:
        severity = 'High'
    elif risk_score >= 30:
        severity = 'Medium'
    else:
        severity = 'Low'

    scored.append({**item, 'riskScore': risk_score, 'severity': severity})

if not scored:
    return [{'isCriticalPath': False, 'riskScore': 0, 'severity': 'None'}]

scored.sort(key=lambda s: s['riskScore'], reverse=True)
top = scored[0]
threshold = float(top.get('riskScoreThreshold', 50))
top['isCriticalPath'] = top['riskScore'] >= threshold

return [top]

