// Parse the AI's structured remediation output and prepare Jira + GitHub payloads
const item = $input.item.json;
const raw = item.output || item.text || item.response || '{}';

let parsed = {};
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    remediationSummary: 'AI response could not be parsed automatically. Manual review required.',
    remediationSteps: [],
    updatedFileContent: null,
    cvssEstimate: null,
    jiraSummary: `Attack path risk detected: ${item.sourceAsset} -> ${item.targetAsset}`,
    jiraDescription: String(raw),
    prBranchName: 'attack-path-fix-' + Date.now(),
    prTitle: 'Remediate attack path finding',
    prBody: String(raw),
    commitMessage: 'Remediate attack path finding'
  };
}

const fileInfo = $('Retrieve IaC File from GitHub').item.json;

return {
  json: {
    ...item,
    remediationSummary: parsed.remediationSummary || '',
    remediationSteps: parsed.remediationSteps || [],
    updatedFileContentBase64: parsed.updatedFileContent ? Buffer.from(parsed.updatedFileContent, 'utf-8').toString('base64') : null,
    cvssEstimate: parsed.cvssEstimate || null,
    jiraSummary: parsed.jiraSummary || `Attack path risk: ${item.sourceAsset} -> ${item.targetAsset}`,
    jiraDescription: parsed.jiraDescription || parsed.remediationSummary || '',
    prBranchName: parsed.prBranchName || ('attack-path-fix-' + Date.now()),
    prTitle: parsed.prTitle || ('Remediate attack path: ' + item.sourceAsset + ' -> ' + item.targetAsset),
    prBody: parsed.prBody || parsed.remediationSummary || '',
    commitMessage: parsed.commitMessage || 'Remediate attack path finding',
    currentFileSha: fileInfo.sha,
    hasFix: !!parsed.updatedFileContent
  }
};
